from rules import resolve


def solve(data):
    return resolve(data)

def _dependency(dep):
    if isinstance(dep, str):
        return dep, None, None
    return dep["name"], dep.get("min"), dep.get("max")


def _within(version, bounds):
    for lower, upper in bounds:
        if lower is not None and version < lower:
            return False
        if upper is not None and version > upper:
            return False
    return True


def _acyclic(assignments, features):
    graph = {}
    for name, row in assignments.items():
        edges = []
        for declaration in row.get("deps", []):
            if not isinstance(declaration, str):
                feature = declaration.get("feature")
                if feature and feature not in features:
                    continue
            dep_name, _, _ = _dependency(declaration)
            edges.append(dep_name)
        graph[name] = edges

    state = {}

    def visit(name):
        if state.get(name) == 1:
            return False
        if state.get(name) == 2:
            return True
        state[name] = 1
        for dep_name in graph.get(name, []):
            if dep_name not in graph or not visit(dep_name):
                return False
        state[name] = 2
        return True

    return all(visit(name) for name in graph)


def resolve(data):
    packages = data["packages"]
    roots = data["roots"]
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    features = set(data.get("features", []))
    names = sorted(packages)

    initial_constraints = {
        name: [(bounds[0], bounds[1])]
        for name, bounds in roots.items()
    }
    best_vector = None
    best_versions = None

    def search(assignments, needed, constraints):
        nonlocal best_vector, best_versions

        pending = needed - set(assignments)
        if not pending:
            if not _acyclic(assignments, features):
                return
            versions = {
                name: row["version"] for name, row in assignments.items()
            }
            vector = tuple(versions.get(name, -1) for name in names)
            if best_vector is None or vector > best_vector:
                best_vector = vector
                best_versions = versions
            return

        name = min(pending)
        for row in packages.get(name, []):
            version = row["version"]
            if version in blocked.get(name, []):
                continue
            if name in pins and version != pins[name]:
                continue
            if not _within(version, constraints.get(name, [])):
                continue

            next_assignments = assignments.copy()
            next_assignments[name] = row
            next_needed = needed.copy()
            next_constraints = {
                package: bounds.copy()
                for package, bounds in constraints.items()
            }
            valid = True

            for declaration in row.get("deps", []):
                if not isinstance(declaration, str):
                    feature = declaration.get("feature")
                    if feature and feature not in features:
                        continue
                dep_name, lower, upper = _dependency(declaration)
                next_needed.add(dep_name)
                next_constraints.setdefault(dep_name, []).append((lower, upper))
                if dep_name in next_assignments and not _within(
                    next_assignments[dep_name]["version"],
                    next_constraints[dep_name],
                ):
                    valid = False
                    break

            if valid:
                search(next_assignments, next_needed, next_constraints)

    search({}, set(roots), initial_constraints)
    if best_versions is None:
        return {"error": "unsatisfiable"}
    return {"versions": best_versions}
